package za.co.loopmanager;
import android.app.ActivityManager;import android.app.admin.DevicePolicyManager;import android.content.*;import android.content.pm.*;import android.os.UserManager;import android.provider.Settings;import org.json.JSONObject;import org.junit.Test;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk={30,35})
public class DeviceSettingsTest {
 private void install(Context c,boolean system){ApplicationInfo app=new ApplicationInfo();app.packageName="com.android.settings";app.enabled=true;app.flags=system?ApplicationInfo.FLAG_SYSTEM:0;PackageInfo pkg=new PackageInfo();pkg.packageName=app.packageName;pkg.applicationInfo=app;Shadows.shadowOf(c.getPackageManager()).installPackage(pkg);for(String action:new String[]{Settings.ACTION_SETTINGS,Settings.ACTION_WIFI_SETTINGS}){ComponentName component=new ComponentName(app.packageName,app.packageName+"."+(action.equals(Settings.ACTION_SETTINGS)?"Settings":"WifiSettings"));ActivityInfo info=Shadows.shadowOf(c.getPackageManager()).addActivityIfNotPresent(component);info.applicationInfo=app;info.enabled=true;info.exported=true;IntentFilter filter=new IntentFilter(action);filter.addCategory(Intent.CATEGORY_DEFAULT);Shadows.shadowOf(c.getPackageManager()).addIntentFilterForActivity(component,filter);}}
 @Test public void onlySystemSettingsMayJoinManagedTask(){Context c=RuntimeEnvironment.getApplication();install(c,false);assertNull(DeviceSettings.target(c,true));assertTrue(DeviceSettings.packages(c).isEmpty());}
 @Test public void systemSettingsRemainAllowedWithoutBankOrCustomer(){Context c=RuntimeEnvironment.getApplication();install(c,true);Shadows.shadowOf(c.getSystemService(DevicePolicyManager.class)).setDeviceOwner(PolicyController.admin(c));BankApps.allowForLock(c,null);assertTrue(java.util.Arrays.asList(c.getSystemService(DevicePolicyManager.class).getLockTaskPackages(PolicyController.admin(c))).contains("com.android.settings"));assertNotNull(DeviceSettings.target(c,true));}
 @Test public void wifiLaunchKeepsManagedLockAndUsesExactSystemActivity(){MainActivity a=Robolectric.buildActivity(MainActivity.class).setup().get();install(a,true);Shadows.shadowOf(a.getSystemService(DevicePolicyManager.class)).setDeviceOwner(PolicyController.admin(a));Shadows.shadowOf(a.getSystemService(ActivityManager.class)).setLockTaskModeState(ActivityManager.LOCK_TASK_MODE_LOCKED);DeviceSettings.open(a,true,null);var started=Shadows.shadowOf(a).getNextStartedActivityForResult();assertEquals(Settings.ACTION_WIFI_SETTINGS,started.intent.getAction());assertEquals("com.android.settings",started.intent.getComponent().getPackageName());assertNotNull(started.options);}
 @Test public void wifiRemainsConfigurableWhileResetAndAppDataAreProtected()throws Exception{Context c=RuntimeEnvironment.getApplication();var pm=c.getSystemService(DevicePolicyManager.class);Shadows.shadowOf(pm).setDeviceOwner(PolicyController.admin(c));Shadows.shadowOf(pm).setActiveAdmin(PolicyController.admin(c));pm.addUserRestriction(PolicyController.admin(c),UserManager.DISALLOW_CONFIG_WIFI);JSONObject data=new JSONObject().put("policy",new JSONObject().put("enforcement_enabled",false).put("block_wifi_changes",true));assertEquals("unrestricted",PolicyController.apply(c,new Entitlement(data,0,-1)));var users=c.getSystemService(UserManager.class);assertFalse(users.hasUserRestriction(UserManager.DISALLOW_CONFIG_WIFI));assertTrue("Settings reset restriction",users.hasUserRestriction(UserManager.DISALLOW_FACTORY_RESET));assertTrue("Safe boot restriction",users.hasUserRestriction(UserManager.DISALLOW_SAFE_BOOT));// User-control package methods are not modeled by Robolectric 4.14; verified by the handset diagnostic.
}
}
